$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "==================================================" -ForegroundColor Cyan
Write-Host " MemeScope Stage 16 - High Quality Signal Engine" -ForegroundColor Cyan
Write-Host "==================================================" -ForegroundColor Cyan
Write-Host ""

$root = (Get-Location).Path
$utf8 = New-Object System.Text.UTF8Encoding($false)

$required = @(
  "src/lib/signal-types.ts",
  "src/lib/signal-engine.ts",
  "src/app/signals/page.tsx",
  "src/components/signal-performance-panel.tsx",
  "src/lib/signal-exit-plan.ts",
  "src/lib/signal-recorder-db.ts"
)

foreach ($relative in $required) {
  $full = Join-Path $root $relative
  if (!(Test-Path -LiteralPath $full)) {
    throw "Required file not found: $relative"
  }
}

# Backup outside the repository so git add . will not include it.
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backup = Join-Path $env:TEMP "MemeScope-Stage16-$stamp"
New-Item -ItemType Directory -Force -Path $backup | Out-Null

foreach ($relative in $required) {
  $src = Join-Path $root $relative
  $safeName = ($relative -replace '[\\/]', '__')
  Copy-Item -LiteralPath $src -Destination (Join-Path $backup $safeName) -Force
}

Write-Host "Backup created: $backup" -ForegroundColor DarkGray
Write-Host ""

# =========================================================
# Validate and prepare recorder patch BEFORE writing anything.
# =========================================================

$recorderPath = Join-Path $root "src/lib/signal-recorder-db.ts"
$recorder = [System.IO.File]::ReadAllText($recorderPath)
$patchedRecorder = $recorder

# 1) Remove the automatic stop-loss close condition.
$stopPattern = '(?s)if\s*\(gain\s*!==\s*null\s*&&\s*gain\s*>=\s*record\.targetPercent\)\s*\{\s*status\s*=\s*"target_hit";\s*\}\s*else\s+if\s*\(gain\s*!==\s*null\s*&&\s*gain\s*<=\s*-record\.stopLossPercent\)\s*\{\s*status\s*=\s*"stop_loss";\s*\}'

if ([regex]::IsMatch($patchedRecorder, $stopPattern)) {
$replacement = @'
if (gain !== null && gain >= record.targetPercent) {
      status = "target_hit";
    }
'@
  $patchedRecorder = [regex]::Replace(
    $patchedRecorder,
    $stopPattern,
    $replacement,
    1
  )
  Write-Host "Recorder lifecycle: automatic stop loss removed." -ForegroundColor Green
}
elseif ($patchedRecorder -match 'gain\s*<=\s*-record\.stopLossPercent') {
  throw "Stop-loss condition exists but did not match the expected structure. No source files were written."
}
else {
  Write-Host "Recorder lifecycle: stop-loss close is already absent." -ForegroundColor Yellow
}

# 2) New records keep the old DB columns for compatibility, but no stop price is created.
$oldStopPrice = '${stopPrice(entry, plan.stopLossPercent)},'
if ($patchedRecorder.Contains($oldStopPrice)) {
  $patchedRecorder = $patchedRecorder.Replace($oldStopPrice, 'NULL,')
  Write-Host "Recorder insert: stop price disabled for new records." -ForegroundColor Green
}

# Remove the helper when it is no longer used.
$stopHelperPattern = '(?ms)\r?\nfunction stopPrice\(entry:\s*number,\s*pct:\s*number\)\s*\{\s*return entry \* \(1 - pct / 100\);\s*\}\r?\n'
if ([regex]::IsMatch($patchedRecorder, $stopHelperPattern)) {
  $patchedRecorder = [regex]::Replace(
    $patchedRecorder,
    $stopHelperPattern,
    "`r`n",
    1
  )
}

# 3) Require two consecutive server detections before opening a history record.
$confirmationPattern = '(?s)  for \(const signal of watchSignals\) \{\s*let state = states\.get\(signal\.id\);\s*let mayOpen = false;\s*if \(!state\) \{.*?    if \(activeIds\.has\(signal\.id\) \|\| !mayOpen\) continue;'

if ([regex]::IsMatch($patchedRecorder, $confirmationPattern)) {
$confirmationReplacement = @'
  // Stage 16: two-scan confirmation.
  // First detection only arms the setup. A second consecutive detection opens it.
  for (const signal of watchSignals) {
    let state = states.get(signal.id);
    let mayOpen = false;

    if (!state) {
      state = { visible: true, armed: true };
      states.set(signal.id, state);

      await sql`
        INSERT INTO memescope_signal_state (
          signal_id, visible, armed, updated_at
        )
        VALUES (${signal.id}, TRUE, TRUE, NOW())
        ON CONFLICT (signal_id)
        DO UPDATE SET
          visible = TRUE,
          armed = TRUE,
          updated_at = NOW()
      `;
    } else if (!state.visible && state.armed) {
      // Reappearance = confirmation scan #1.
      state.visible = true;

      await sql`
        UPDATE memescope_signal_state
        SET visible = TRUE, armed = TRUE, updated_at = NOW()
        WHERE signal_id = ${signal.id}
      `;
    } else if (state.visible && state.armed) {
      // Consecutive detection = confirmation scan #2.
      mayOpen = true;
      state.armed = false;

      await sql`
        UPDATE memescope_signal_state
        SET visible = TRUE, armed = FALSE, updated_at = NOW()
        WHERE signal_id = ${signal.id}
      `;
    } else if (!state.visible) {
      state.visible = true;

      await sql`
        UPDATE memescope_signal_state
        SET visible = TRUE, updated_at = NOW()
        WHERE signal_id = ${signal.id}
      `;
    }

    if (activeIds.has(signal.id) || !mayOpen) continue;
'@
  $patchedRecorder = [regex]::Replace(
    $patchedRecorder,
    $confirmationPattern,
    $confirmationReplacement,
    1
  )
  Write-Host "Recorder confirmation: 2 consecutive scans enabled." -ForegroundColor Green
}
elseif ($patchedRecorder.Contains("Stage 16: two-scan confirmation.")) {
  Write-Host "Recorder confirmation: Stage 16 logic already present." -ForegroundColor Yellow
}
else {
  throw "Could not locate the recorder state block for two-scan confirmation. No source files were written."
}

# Final recorder validation.
if ($patchedRecorder -match 'gain\s*<=\s*-record\.stopLossPercent') {
  throw "Validation failed: stop-loss close condition still exists. No source files were written."
}

if (!$patchedRecorder.Contains("Stage 16: two-scan confirmation.")) {
  throw "Validation failed: two-scan confirmation was not installed. No source files were written."
}

# =========================================================
# Embedded exact replacements generated from the source files
# supplied for Stage 16.
# =========================================================

$payloads = @{}

$payloads["src/lib/signal-types.ts"] = @"

"@

$payloads["src/lib/signal-engine.ts"] = @"

"@

$payloads["src/app/signals/page.tsx"] = @"

"@

$payloads["src/components/signal-performance-panel.tsx"] = @"

"@

$payloads["src/lib/signal-exit-plan.ts"] = @"

"@

function Write-Base64Utf8File {
  param(
    [Parameter(Mandatory=$true)][string]$RelativePath,
    [Parameter(Mandatory=$true)][string]$Base64Text
  )

  $fullPath = Join-Path $root $RelativePath
  $bytes = [Convert]::FromBase64String(($Base64Text -replace '\s', ''))
  [System.IO.File]::WriteAllBytes($fullPath, $bytes)
}

# Write the exact Stage 16 payloads.
foreach ($entry in $payloads.GetEnumerator()) {
  Write-Base64Utf8File -RelativePath $entry.Key -Base64Text $entry.Value
  Write-Host "Updated: $($entry.Key)" -ForegroundColor Green
}

# Write the validated recorder patch last.
[System.IO.File]::WriteAllText(
  $recorderPath,
  $patchedRecorder,
  $utf8
)
Write-Host "Updated: src/lib/signal-recorder-db.ts" -ForegroundColor Green

Remove-Item -Recurse -Force (Join-Path $root ".next") -ErrorAction SilentlyContinue

Write-Host ""
Write-Host "==================================================" -ForegroundColor Green
Write-Host " Stage 16 installed" -ForegroundColor Green
Write-Host "==================================================" -ForegroundColor Green
Write-Host ""
Write-Host "Stage 16 behavior:" -ForegroundColor Cyan
Write-Host " - strict high-quality hard filters"
Write-Host " - signal score floor 80"
Write-Host " - volume spike alone cannot create a signal"
Write-Host " - controlled 5m / 1h momentum filters"
Write-Host " - liquidity / market-cap depth filter"
Write-Host " - buy-pressure and transaction participation filters"
Write-Host " - 2 consecutive detections required"
Write-Host " - analysis-based Potential TP"
Write-Host " - no automatic stop loss for new records"
Write-Host " - Max Gain and Max Drawdown remain tracked"
Write-Host " - old database records are preserved"
Write-Host ""
Write-Host "Important:" -ForegroundColor Yellow
Write-Host "Potential TP and Signal Score are heuristic analytics, not guaranteed outcomes."
Write-Host "Contract / holder risk is still verified separately through Analyze Risk."
Write-Host ""
Write-Host "Next:" -ForegroundColor Cyan
Write-Host "npm run typecheck"
Write-Host "npm run build"
Write-Host ""
